Siwi.platformer({
  title: "Puff's Desert Garden",
  assets: window.SIWI_ASSETS || {},
  palette: { sky: "#AEE3F5", skyBottom: "#FFE6B8", ground: "#D9A066", groundTop: "#8CC084", accent: "#4FB6D9", collectible: "#4FB6D9", enemy: "#B07A4A", hazard: "#5A9A5A", player: "#FFFFFF" },
  player: { speed: 260, jump: 640, lives: 3 },
  gravity: 1800,
  winText: "The oasis blooms!",
  loseText: "Puff dozed off... Try again",
  legend: {
    "#": { type: "solid", sprite: "tile" },
    "=": { type: "solid", sprite: "platform" },
    "-": { type: "oneway", sprite: "platform" },
    "C": { type: "collectible", sprite: "collectible", value: 10 },
    "E": { type: "enemy", sprite: "enemy", speed: 70, stompable: true, value: 50 },
    "F": { type: "enemy", sprite: "enemy2", speed: 0, flying: true, amplitude: 60, stompable: true, value: 50 },
    "^": { type: "hazard", sprite: "hazard" },
    "G": { type: "goal", sprite: "goal", size: 64 },
    "U": { type: "powerup", sprite: "powerup", power: "doubleJump", label: "double jump" },
    "S": {
      type: "custom", sprite: "sprout", size: 40,
      update(e, api, dt) { if (e) e.t = (e.t || 0) + (dt || 0); },
      touch(e, api) {
        if (!e || !api || !api.player || !api.state) return;
        const p = api.player;
        const g = api.state.gravity || 1;
        if (e.bloomed) {
          if (p.vy * g > 0 && p.y < e.y + 10) {
            p.vy = -950 * g;
            if (api.sfx && api.sfx.jump) api.sfx.jump();
            if (api.burst) api.burst(e.x + 20, e.y, "#FF8FB5", 8, 140);
          }
          return;
        }
        if (DROPS.n > 0) {
          DROPS.n--;
          e.bloomed = true;
          e.sprite = "bloom";
          if (api.addScore) api.addScore(25, e.x + 20, e.y);
          if (api.sfx && api.sfx.power) api.sfx.power();
          if (api.burst) api.burst(e.x + 20, e.y, "#8CC084", 12, 160);
          if (api.floatText) api.floatText("Bloom!", e.x + 20, e.y - 10, "#FF6FA5");
        } else if (api.floatText && api.state.frame - (e.hint || -999) > 90) {
          e.hint = api.state.frame;
          api.floatText("Need raindrop!", e.x + 20, e.y - 10, "#4FB6D9");
        }
      },
      draw(ctx, e, api) {
        if (!ctx || !e || !api) return;
        const imgs = api.images || {};
        const img = e.bloomed ? imgs.bloom : imgs.sprout;
        if (img) { ctx.drawImage(img, e.x - 4, e.y - 8, 48, 48); return; }
        if (e.bloomed) {
          ctx.fillStyle = "#5FBF6A"; ctx.fillRect(e.x + 16, e.y + 18, 8, 22);
          ctx.fillStyle = "#FF8FB5";
          ctx.beginPath(); ctx.arc(e.x + 20, e.y + 12, 14, 0, 7); ctx.fill();
          ctx.fillStyle = "#4FB6D9";
          ctx.beginPath(); ctx.arc(e.x + 20, e.y + 12, 6, 0, 7); ctx.fill();
        } else {
          ctx.fillStyle = "#8a6a45"; ctx.fillRect(e.x + 8, e.y + 28, 24, 10);
          ctx.fillStyle = "#7AAE5A"; ctx.fillRect(e.x + 17, e.y + 10, 6, 20);
        }
      }
    }
  },
  levels: [
    { name: "Drowsy Dunes", rows: L1, background: "background" },
    { name: "Moonlit Oasis Bloom", rows: L2, background: "background" }
  ],
  hooks: {
    onLevelStart(api) { DROPS.n = 0; },
    onCollect(item, api) {
      DROPS.n++;
      if (api && api.floatText && item) api.floatText("+drop", item.x, item.y - 12, "#4FB6D9");
    },
    onStomp(enemy, api) { if (api && api.floatText && enemy) api.floatText("Poof!", enemy.x, enemy.y - 10, "#FFFFFF"); },
    onDraw(ctx, api) {
      if (!ctx || !api || !api.state) return;
      if (api.state.time < 4 && api.state.status === "playing") {
        Siwi.text(ctx, "Grab drops, touch sprouts to bloom, bounce up!", 480, 60, 20, "#5A4A3A", "center");
        Siwi.text(ctx, "Drops: " + DROPS.n, 480, 86, 18, "#4FB6D9", "center");
      }
    }
  }
});

